-- Meridian Paid Beta Push 3. Additive payment and Auto-Refill state.
create table public.billing_accounts(id uuid primary key default gen_random_uuid(),organization_id uuid not null unique references public.organizations(id) on delete cascade,provider text not null default 'PADDLE' check(provider='PADDLE'),environment text not null check(environment in('sandbox','live')),paddle_customer_id text not null,paddle_subscription_id text,payment_profile_status text not null default 'NOT_CONFIGURED' check(payment_profile_status in('NOT_CONFIGURED','PENDING','ACTIVE','PAYMENT_ATTENTION_REQUIRED','CANCELED','ERROR')),payment_method_type text,payment_method_brand text,payment_method_last_four text check(payment_method_last_four is null or payment_method_last_four~'^[0-9]{4}$'),payment_method_expiry_month integer check(payment_method_expiry_month between 1 and 12),payment_method_expiry_year integer,activated_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),metadata jsonb not null default '{}',unique(environment,paddle_customer_id),unique(environment,paddle_subscription_id));
create table public.payment_checkout_attempts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,requested_by uuid references auth.users(id) on delete set null,checkout_type text not null check(checkout_type in('PAYMENT_PROFILE','TOKEN_PURCHASE')),token_pack integer check(token_pack in(5,20,50,100,250,500)),idempotency_key text not null,status text not null default 'CREATED' check(status in('CREATED','OPENED','COMPLETED','EXPIRED','FAILED')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,idempotency_key));
create table public.payment_transactions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,billing_account_id uuid references public.billing_accounts(id) on delete set null,provider text not null default 'PADDLE' check(provider='PADDLE'),environment text not null check(environment in('sandbox','live')),paddle_transaction_id text not null,paddle_customer_id text not null,paddle_subscription_id text,purchase_type text not null check(purchase_type in('PAYMENT_PROFILE','TOKEN_PURCHASE','AUTO_REFILL')),token_pack integer check(token_pack in(5,20,50,100,250,500)),tokens_granted integer not null default 0 check(tokens_granted>=0),token_lot_id uuid references public.token_lots(id) on delete set null,currency text,subtotal_minor bigint,tax_minor bigint,total_minor bigint,fee_minor bigint,seller_earnings_minor bigint,receipt_url text,status text not null default 'CREATED' check(status in('CREATED','CHECKOUT_OPEN','PENDING','COMPLETED','FAILED','REFUNDED','PARTIALLY_REFUNDED','REQUIRES_REVIEW')),completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),metadata jsonb not null default '{}',unique(environment,paddle_transaction_id));
create table public.paddle_webhook_events(id uuid primary key default gen_random_uuid(),event_id text not null,event_type text not null,occurred_at timestamptz,received_at timestamptz not null default now(),environment text not null check(environment in('sandbox','live')),processing_status text not null default 'RECEIVED' check(processing_status in('RECEIVED','PROCESSING','PROCESSED','FAILED','SKIPPED')),processed_at timestamptz,error text,related_customer_id text,related_transaction_id text,related_subscription_id text,metadata jsonb not null default '{}',unique(environment,event_id));
create table public.auto_refill_settings(id uuid primary key default gen_random_uuid(),organization_id uuid not null unique references public.organizations(id) on delete cascade,enabled boolean not null default false,trigger_tokens integer not null default 10 check(trigger_tokens in(5,10,20)),refill_tokens integer not null default 50 check(refill_tokens in(20,50,100,250)),monthly_cap_usd integer not null default 100 check(monthly_cap_usd in(50,100,250,500) and monthly_cap_usd>=refill_tokens),status text not null default 'DISABLED' check(status in('DISABLED','ACTIVE','PAYMENT_ATTENTION_REQUIRED','CAP_REACHED','PAYMENT_PROFILE_INACTIVE')),consented_at timestamptz,consented_by_user_id uuid references auth.users(id) on delete set null,consent_version text,disabled_at timestamptz,last_attempt_at timestamptz,last_success_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.auto_refill_consent_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,enabled boolean not null,trigger_tokens integer not null,refill_tokens integer not null,monthly_cap_usd integer not null,consent_version text not null,actor_id uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table public.auto_refill_attempts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,trigger_reason text not null check(trigger_reason in('AFTER_RESEARCH','BEFORE_RESEARCH','USER_RETRY')),balance_before integer not null,threshold_tokens integer not null,refill_tokens integer not null,monthly_cap_usd integer not null,month_spend_before_usd integer not null default 0,paddle_transaction_id text,idempotency_key text not null,status text not null default 'CREATED' check(status in('CREATED','PENDING','COMPLETED','FAILED','CAP_BLOCKED','CANCELED')),failure text,created_at timestamptz not null default now(),completed_at timestamptz,unique(organization_id,idempotency_key));
create table public.payment_adjustments(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete set null,paddle_adjustment_id text not null,paddle_transaction_id text,environment text not null check(environment in('sandbox','live')),status text not null,amount_minor bigint,currency text,reconciliation_status text not null default 'PENDING' check(reconciliation_status in('PENDING','REVERSED','REQUIRES_REVIEW')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),metadata jsonb not null default '{}',unique(environment,paddle_adjustment_id));
create unique index auto_refill_one_pending_per_org on public.auto_refill_attempts(organization_id) where status in('CREATED','PENDING'); create index payment_transactions_org_idx on public.payment_transactions(organization_id,created_at desc); create index paddle_webhooks_status_idx on public.paddle_webhook_events(processing_status,received_at);
alter table public.billing_accounts enable row level security;alter table public.payment_checkout_attempts enable row level security;alter table public.payment_transactions enable row level security;alter table public.paddle_webhook_events enable row level security;alter table public.auto_refill_settings enable row level security;alter table public.auto_refill_consent_events enable row level security;alter table public.auto_refill_attempts enable row level security;alter table public.payment_adjustments enable row level security;
revoke all on public.billing_accounts,public.payment_checkout_attempts,public.payment_transactions,public.paddle_webhook_events,public.auto_refill_settings,public.auto_refill_consent_events,public.auto_refill_attempts,public.payment_adjustments from anon,authenticated;grant select on public.billing_accounts,public.payment_checkout_attempts,public.payment_transactions,public.paddle_webhook_events,public.auto_refill_settings,public.auto_refill_consent_events,public.auto_refill_attempts,public.payment_adjustments to authenticated;
create policy billing_accounts_read on public.billing_accounts for select to authenticated using((select private.is_admin()) or organization_id in(select private.user_organization_ids()));create policy payment_transactions_read on public.payment_transactions for select to authenticated using((select private.is_admin()) or organization_id in(select private.user_organization_ids()));create policy auto_refill_settings_read on public.auto_refill_settings for select to authenticated using((select private.is_admin()) or organization_id in(select private.user_organization_ids()));create policy auto_refill_consents_read on public.auto_refill_consent_events for select to authenticated using((select private.is_admin()) or organization_id in(select private.user_organization_ids()));create policy auto_refill_attempts_read on public.auto_refill_attempts for select to authenticated using((select private.is_admin()) or organization_id in(select private.user_organization_ids()));create policy payment_checkout_admin_read on public.payment_checkout_attempts for select to authenticated using((select private.is_admin()));create policy paddle_webhooks_admin_read on public.paddle_webhook_events for select to authenticated using((select private.is_admin()));create policy payment_adjustments_admin_read on public.payment_adjustments for select to authenticated using((select private.is_admin()));
create or replace function public.save_auto_refill_settings(trigger_value integer,refill_value integer,cap_value integer,enable_value boolean,consent text default '2026-09-04') returns jsonb language plpgsql security definer set search_path='' as $$ declare org uuid;profile_status text;result public.auto_refill_settings;begin select organization_id into org from public.organization_members where user_id=(select auth.uid()) limit 1;if org is null then raise exception 'No client organization.';end if;if trigger_value not in(5,10,20) or refill_value not in(20,50,100,250) or cap_value not in(50,100,250,500) or cap_value<refill_value then raise exception 'Invalid Auto-Refill configuration.';end if;select payment_profile_status into profile_status from public.billing_accounts where organization_id=org;if enable_value and profile_status<>'ACTIVE' then raise exception 'An active Payment Profile is required.';end if;insert into public.auto_refill_settings(organization_id,enabled,trigger_tokens,refill_tokens,monthly_cap_usd,status,consented_at,consented_by_user_id,consent_version,disabled_at) values(org,enable_value,trigger_value,refill_value,cap_value,case when enable_value then 'ACTIVE' else 'DISABLED' end,case when enable_value then now() end,case when enable_value then auth.uid() end,case when enable_value then consent end,case when not enable_value then now() end) on conflict(organization_id) do update set enabled=excluded.enabled,trigger_tokens=excluded.trigger_tokens,refill_tokens=excluded.refill_tokens,monthly_cap_usd=excluded.monthly_cap_usd,status=excluded.status,consented_at=case when excluded.enabled then now() else public.auto_refill_settings.consented_at end,consented_by_user_id=case when excluded.enabled then auth.uid() else public.auto_refill_settings.consented_by_user_id end,consent_version=case when excluded.enabled then consent else public.auto_refill_settings.consent_version end,disabled_at=case when not excluded.enabled then now() else null end,updated_at=now() returning * into result;insert into public.auto_refill_consent_events(organization_id,enabled,trigger_tokens,refill_tokens,monthly_cap_usd,consent_version,actor_id) values(org,enable_value,trigger_value,refill_value,cap_value,consent,auth.uid());return to_jsonb(result);end $$;
create or replace function public.grant_paddle_purchase(target_org uuid,target_transaction text,target_tokens integer,target_environment text,details jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$ declare wallet uuid;lot uuid;created boolean:=false;begin if auth.role()<>'service_role' then raise exception 'Service authorization required.';end if;if target_tokens not in(5,20,50,100,250,500) then raise exception 'Invalid Token pack.';end if;perform pg_advisory_xact_lock(hashtext(target_environment||':'||target_transaction));select id into lot from public.token_lots where organization_id=target_org and idempotency_key='paddle:'||target_environment||':'||target_transaction;if lot is null then insert into public.token_wallets(organization_id) values(target_org) on conflict(organization_id) do update set updated_at=now() returning id into wallet;insert into public.token_lots(wallet_id,organization_id,kind,initial_tokens,available_tokens,expires_at,source_type,source_reference,idempotency_key,metadata) values(wallet,target_org,'PURCHASED',target_tokens,target_tokens,null,'PADDLE_TRANSACTION',target_transaction,'paddle:'||target_environment||':'||target_transaction,details) returning id into lot;insert into public.token_ledger(organization_id,token_lot_id,event_type,token_delta,idempotency_key,reason,actor_type,metadata) values(target_org,lot,'PURCHASE_GRANT',target_tokens,'purchase:'||target_environment||':'||target_transaction,target_tokens||' Token Paddle purchase','PAYMENT',details);created:=true;end if;return jsonb_build_object('token_lot_id',lot,'tokens',target_tokens,'created',created);end $$;
create or replace function public.activate_paddle_beta(target_org uuid,target_reference text) returns jsonb language plpgsql security definer set search_path='' as $$ declare wallet uuid;lot uuid;expiry timestamptz;created boolean:=false;begin if auth.role()<>'service_role' then raise exception 'Service authorization required.';end if;perform pg_advisory_xact_lock(hashtext(target_org::text||':BETA_ACTIVATION'));insert into public.token_wallets(organization_id) values(target_org) on conflict(organization_id) do update set updated_at=now() returning id into wallet;select id,expires_at into lot,expiry from public.token_lots where organization_id=target_org and source_type='BETA_ACTIVATION' limit 1;if lot is null then expiry:=now()+interval '14 days';insert into public.token_lots(wallet_id,organization_id,kind,initial_tokens,available_tokens,expires_at,source_type,source_reference,idempotency_key) values(wallet,target_org,'PROMOTIONAL',20,20,expiry,'BETA_ACTIVATION',target_reference,'BETA_ACTIVATION') returning id into lot;insert into public.token_ledger(organization_id,token_lot_id,event_type,token_delta,idempotency_key,reason,actor_type) values(target_org,lot,'PROMO_GRANT',20,'promo:BETA_ACTIVATION','20-Token verified Paddle activation grant','PAYMENT');created:=true;end if;return jsonb_build_object('token_lot_id',lot,'tokens',20,'expires_at',expiry,'created',created);end $$;
create or replace function public.reconcile_paddle_refund(target_transaction text,target_environment text,details jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$ declare payment public.payment_transactions;lot public.token_lots;begin if auth.role()<>'service_role' then raise exception 'Service authorization required.';end if;select * into payment from public.payment_transactions where paddle_transaction_id=target_transaction and environment=target_environment for update;if payment.id is null then raise exception 'Payment not found.';end if;select * into lot from public.token_lots where id=payment.token_lot_id for update;if lot.id is not null and lot.available_tokens=lot.initial_tokens and lot.reserved_tokens=0 then update public.token_lots set available_tokens=0,updated_at=now() where id=lot.id;insert into public.token_ledger(organization_id,token_lot_id,event_type,token_delta,idempotency_key,reason,actor_type,metadata) values(payment.organization_id,lot.id,'REVERSAL',-lot.available_tokens,'paddle-refund:'||target_environment||':'||target_transaction,'Full unused Paddle refund','PAYMENT',details) on conflict do nothing;update public.payment_transactions set status='REFUNDED',updated_at=now() where id=payment.id;return jsonb_build_object('status','REFUNDED');else update public.payment_transactions set status='REQUIRES_REVIEW',metadata=metadata||details,updated_at=now() where id=payment.id;return jsonb_build_object('status','REQUIRES_REVIEW');end if;end $$;
revoke all on function public.save_auto_refill_settings(integer,integer,integer,boolean,text),public.grant_paddle_purchase(uuid,text,integer,text,jsonb),public.activate_paddle_beta(uuid,text),public.reconcile_paddle_refund(text,text,jsonb) from public,anon,authenticated;grant execute on function public.save_auto_refill_settings(integer,integer,integer,boolean,text) to authenticated;grant execute on function public.grant_paddle_purchase(uuid,text,integer,text,jsonb),public.activate_paddle_beta(uuid,text),public.reconcile_paddle_refund(text,text,jsonb) to service_role;
drop trigger if exists billing_accounts_updated_at on public.billing_accounts;create trigger billing_accounts_updated_at before update on public.billing_accounts for each row execute function public.set_updated_at();drop trigger if exists payment_transactions_updated_at on public.payment_transactions;create trigger payment_transactions_updated_at before update on public.payment_transactions for each row execute function public.set_updated_at();drop trigger if exists auto_refill_settings_updated_at on public.auto_refill_settings;create trigger auto_refill_settings_updated_at before update on public.auto_refill_settings for each row execute function public.set_updated_at();
